begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,raw_user_meta_data)
select ('af000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid,'av'||n||'@example.invalid',jsonb_build_object('display_name','Friend '||n) from generate_series(1,6)n;
create function pg_temp.scheduled(minutes integer default 60) returns uuid language plpgsql as $$
declare p uuid; token uuid; begin
 p:=(public.pick_create_options('af000000-0000-4000-8000-000000000001',jsonb_build_object('category','food','center',jsonb_build_object('lat',40,'lng',-73),'radiusM',3000,'poolSize',10,'closeThreshold',100,'deadlineAt',null,'proposedAt',now()+interval '2 days','swipeDeadlineMinutes',minutes))->>'id')::uuid;
 token:=(public.pick_availability_claim(p::text,'af000000-0000-4000-8000-000000000001')->>'token')::uuid;
 perform public.pick_availability_finish(p::text,'af000000-0000-4000-8000-000000000001',token,'[{"placeId":"av-cafe-a","snapshot":{"name":"Cafe A","lat":40,"lng":-73}},{"placeId":"av-cafe-b","snapshot":{"name":"Cafe B","lat":40,"lng":-73}}]');
 return p;
end $$;
create temp table av_fixture(id uuid);
insert into av_fixture values(pg_temp.scheduled());
insert into pick_participants(pick_id,user_id) select f.id,('af000000-0000-4000-8000-'||lpad(n::text,12,'0'))::uuid from av_fixture f cross join generate_series(2,5)n;
select is((select state::text from picks where id=(select id from av_fixture)),'swiping','scheduled creation is immediately swipe-ready with host alone');
select is((select availability_locked_at from picks where id=(select id from av_fixture)),null::timestamptz,'final cohort is not locked at creation');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),0::bigint,'no premature final cohort');
select ok((select deadline_at between now()+interval '59 minutes' and now()+interval '61 minutes' from picks where id=(select id from av_fixture)),'deadline begins at initialization');
select is((select response from pick_availability where pick_id=(select id from av_fixture)),'yes','host initialized Yes');
select lives_ok($$select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001','av-cafe-a',2)$$,'host can swipe immediately');
select throws_ok($$select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002','av-cafe-a',2)$$,'PT403','Confirm Yes or Maybe before participating','no response cannot swipe');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000006',1,'yes')$$,'PT404','Pick not found','stranger cannot respond');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'invalid')$$,'PT400','Invalid availability response','invalid response rejected');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',2,'yes')$$,'PT409','Time changed; refresh this Pick','stale revision rejected');
select lives_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'yes')$$,'late Yes joins active round independently');
select lives_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',1,'maybe')$$,'late Maybe joins active round independently');
select lives_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',1,'maybe')$$,'ambiguous response retry is idempotent while the round remains open');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004',1,'cant');
select throws_ok($$select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004','av-cafe-a',2)$$,'PT403','Confirm Yes or Maybe before participating','Cant cannot swipe');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',1,'cant');
select is(jsonb_array_length(public.pick_load_for_close((select id::text from av_fixture))->'participantIds'),2,'decline before participation removes only eligibility');
select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',1,'maybe');
select public.heartbeat_upsert_swipe((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002','av-cafe-a',2);
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'cant')$$,'PT409','Your voting response is kept after your first swipe. Update attendance after results.','first swipe freezes eligibility-bearing decline');
select lives_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002',1,'maybe')$$,'Yes to Maybe preserves participation');
select is((select count(*) from preferences where pick_id=(select id from av_fixture) and user_id='af000000-0000-4000-8000-000000000002'),1::bigint,'availability edits never erase submitted swipes');
select is((public.pick_load_for_close((select id::text from av_fixture))->>'awaitingResponses')::integer,1,'awaiting is distinct from eligible and declined');
select is(jsonb_array_length(public.pick_load_for_close((select id::text from av_fixture))->'participantIds'),3,'ranking denominator excludes Cant and no response');
select throws_ok($$select public.pick_close_apply(id::text,'system',null,(select version::text from picks where id=av_fixture.id),'{}') from av_fixture$$,'PT409','Invitations are still unanswered','default auto close waits for unanswered invitation');
select throws_ok($$select public.pick_availability_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001',1,now()+interval '3 days')$$,'PT409','The proposed time is fixed for this decision. Revisit scheduling after results.','host cannot silently change active proposed time');
select set_config('wtw.availability_pick',(select id::text from av_fixture),true);
select set_config('request.jwt.claim.sub','af000000-0000-4000-8000-000000000004',true);
set local role authenticated;
select is((select count(*) from pick_candidates where pick_id=current_setting('wtw.availability_pick')::uuid),0::bigint,'RLS hides swipe deck from declined invitee');
select ok(not has_table_privilege('authenticated','public.pick_availability','insert'),'authenticated cannot write availability directly');
select ok(not has_function_privilege('authenticated','public.pick_availability_respond(text,uuid,integer,text)','execute'),'authenticated cannot spoof RPC actor');
reset role;
-- Canonical manual closure includes Yes/Maybe even with partial swipes, like normal Picks.
select public.pick_close_apply(id::text,'host','af000000-0000-4000-8000-000000000001',(select version::text from picks where id=av_fixture.id),jsonb_build_object('state','final_vote','winnerPlaceId',null,'voteDeadlineAt',now()+interval '30 minutes','rows','[{"place_id":"av-cafe-a","rank":1,"score":80,"finalist":true},{"place_id":"av-cafe-b","rank":2,"score":70,"finalist":true}]'::jsonb)) from av_fixture;
select is((select state::text from picks where id=(select id from av_fixture)),'final_vote','manual close ignores unanswered invitations');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),3::bigint,'final cohort freezes atomically at closure');
select isnt((select availability_locked_at from picks where id=(select id from av_fixture)),null::timestamptz,'closure records final cohort lock');
select is((select count(*) from pick_participants where pick_id=(select id from av_fixture)),5::bigint,'decline never deletes invitation or group membership');
select throws_ok($$select public.pick_availability_respond((select id::text from av_fixture),'af000000-0000-4000-8000-000000000005',1,'yes')$$,'PT409','The swipe round has closed; refresh this Pick','late Yes cannot expand final cohort');
select throws_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000005','av-cafe-a')$$,'PT403','Confirm Yes or Maybe before participating','nonresponder cannot cast final vote');
select throws_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000004','av-cafe-a')$$,'PT403','Confirm Yes or Maybe before participating','declined invitee cannot cast final vote');
select lives_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003','av-cafe-a')$$,'Maybe partial swiper may vote in frozen cohort');
select lives_ok($$select public.pick_cast_vote((select id::text from av_fixture),'af000000-0000-4000-8000-000000000002','av-cafe-a')$$,'confirmed participant can vote');
insert into blocks(blocker_id,blocked_id) values('af000000-0000-4000-8000-000000000001','af000000-0000-4000-8000-000000000002');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_fixture)),2::bigint,'security revocation overrides locked cohort');
select is((select count(*) from final_votes where pick_id=(select id from av_fixture)),1::bigint,'revocation removes only revoked ballot');
select public.pick_close_vote_apply((select id::text from av_fixture),'av-cafe-a','vote');
select is((select plan_at from picks where id=(select id from av_fixture)),(select proposed_at from picks where id=(select id from av_fixture)),'original proposal reaches winner unchanged');
select public.pick_rsvp((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003','going');
select lives_ok($$select public.pick_set_plan_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000001',now()+interval '3 days')$$,'host can revisit time after results');
select is((select winner_place_id from picks where id=(select id from av_fixture)),'av-cafe-a','rescheduling never changes winner');
select is((select count(*) from pick_rsvps where pick_id=(select id from av_fixture)),0::bigint,'new time requires final RSVP reconfirmation');
select is((select count(*) from pick_outcomes where pick_id=(select id from av_fixture)),0::bigint,'availability and rescheduling never create attendance');
select throws_ok($$select public.pick_set_plan_time((select id::text from av_fixture),'af000000-0000-4000-8000-000000000003',now()+interval '4 days')$$,'PT403','Only the host can set the time','participants cannot unilaterally reschedule');
create temp table av_other(id uuid);
insert into av_other values(pg_temp.scheduled(0));
select is((select deadline_at from picks where id=(select id from av_other)),null::timestamptz,'No deadline remains null');
select throws_ok($$select public.pick_close_apply(id::text,'system',null,(select version::text from picks where id=av_other.id),'{}') from av_other$$,'PT409','Invitations are still unanswered','host-only default round leaves a chance to invite friends');
select lives_ok($$select public.pick_cancel((select id::text from av_other),'af000000-0000-4000-8000-000000000001',null)$$,'No-deadline round remains cancellable');
select throws_ok($$select public.pick_availability_respond((select id::text from av_other),'af000000-0000-4000-8000-000000000001',1,'yes')$$,'PT409','The swipe round has closed; refresh this Pick','cancellation blocks pending responses');
-- Failed initialization cannot publish a partial deck or transition.
create temp table av_failed(id uuid, token uuid);
insert into av_failed(id) select (public.pick_create_options('af000000-0000-4000-8000-000000000001',jsonb_build_object('category','food','center',jsonb_build_object('lat',40,'lng',-73),'radiusM',3000,'poolSize',10,'closeThreshold',100,'deadlineAt',null,'proposedAt',now()+interval '2 days','swipeDeadlineMinutes',60))->>'id')::uuid;
update av_failed set token=(public.pick_availability_claim(id::text,'af000000-0000-4000-8000-000000000001')->>'token')::uuid;
select throws_ok($$select public.pick_availability_finish(id::text,'af000000-0000-4000-8000-000000000001',token,'[]') from av_failed$$,'PT400','At least one candidate is required to start','invalid initialization fails atomically');
select is((select state::text from picks where id=(select id from av_failed)),'draft','failed initialization remains draft');
select is((select count(*) from pick_candidates where pick_id=(select id from av_failed)),0::bigint,'failed initialization has no partial deck');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_failed)),0::bigint,'failed initialization has no partial final cohort');
-- Default completion may freeze once everyone responds; declining is not completion.
create temp table av_ready(id uuid);
insert into av_ready values(pg_temp.scheduled(0));
insert into pick_participants(pick_id,user_id) select id,'af000000-0000-4000-8000-000000000003' from av_ready;
select public.pick_availability_respond(id::text,'af000000-0000-4000-8000-000000000003',1,'cant') from av_ready;
select is(jsonb_array_length(public.pick_load_for_close((select id::text from av_ready))->'participantIds'),1,'declined participant is excluded from completion denominator');
select lives_ok($$select private.availability_freeze(id::text,(select version::text from picks where id=av_ready.id),'system',null) from av_ready$$,'all answered invitations release default completion guard');
select is((select count(*) from pick_voting_cohort where pick_id=(select id from av_ready)),1::bigint,'declined participant never enters final cohort');
-- The last Yes/Maybe cannot decline, or the round could never close and would stay swiping.
create temp table av_sole(id uuid);
insert into av_sole values(pg_temp.scheduled());
insert into pick_participants(pick_id,user_id) select id,'af000000-0000-4000-8000-000000000002' from av_sole;
select throws_ok($$select public.pick_availability_respond(id::text,'af000000-0000-4000-8000-000000000001',1,'cant') from av_sole$$,'PT409','Someone has to be able to go. Cancel the Pick instead.','sole eligible host cannot decline');
select public.pick_availability_respond(id::text,'af000000-0000-4000-8000-000000000002',1,'yes') from av_sole;
select lives_ok($$select public.pick_availability_respond(id::text,'af000000-0000-4000-8000-000000000001',1,'cant') from av_sole$$,'host may decline once another participant can go');
select throws_ok($$select public.pick_availability_respond(id::text,'af000000-0000-4000-8000-000000000002',1,'cant') from av_sole$$,'PT409','Someone has to be able to go. Cancel the Pick instead.','last remaining eligible participant cannot decline');
select * from finish();
rollback;
